package workbench.concurrency.l11;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/** A record's fields are final. The objects they point to are not. */
public class ShallowRecord {
    record ShallowQuote(String pair, List<String> tiers, byte[] signature) {}

    record DeepQuote(String pair, List<String> tiers, byte[] signature) {
        DeepQuote {
            tiers = List.copyOf(tiers);                        // copy in
            signature = signature.clone();
        }

        @Override
        public byte[] signature() {
            return signature.clone();                          // copy out
        }
    }

    public static void main(String[] args) {
        List<String> tiers = new ArrayList<>(List.of("up to 10k at 1.0842"));
        byte[] sig = {7, 7, 7};
        ShallowQuote shallow = new ShallowQuote("EURUSD", tiers, sig);
        DeepQuote deep = new DeepQuote("EURUSD", tiers, sig);
        List<String> view = Collections.unmodifiableList(tiers);   // a read-only VIEW, not a copy

        tiers.add("above 10k at 9.9999");                      // the caller keeps changing its list...
        sig[0] = 0;                                            // ...and its array
        shallow.signature()[1] = 0;                            // a reader scribbles on what it was given
        deep.signature()[1] = 0;

        System.out.println("shallow: " + shallow.tiers() + "  signature " + Arrays.toString(shallow.signature()));
        System.out.println("deep:    " + deep.tiers() + "  signature " + Arrays.toString(deep.signature()));
        System.out.println("unmodifiableList view: " + view);
    }
}

package workbench.concurrency.l11;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

/**
 * A request thread fills batches of 100 ledger entries and hands each one to a writer thread
 * through a queue. Run with -Pargs=reuse to reuse one list instead of handing over a new one.
 */
public class HandOff {
    public static void main(String[] args) throws InterruptedException {
        boolean reuse = args.length > 0 && args[0].equals("reuse");
        BlockingQueue<List<Integer>> queue = new ArrayBlockingQueue<>(4);
        int batches = 5_000;
        int[] damaged = {0};

        Thread writer = new Thread(() -> {
            try {
                for (int b = 0; b < batches; b++) {
                    List<Integer> batch = queue.take();               // the writer owns this list now
                    try {
                        Object[] entries = batch.toArray();
                        boolean ok = entries.length == 100;
                        for (int i = 0; ok && i < 100; i++) ok = entries[i].equals(((Integer) entries[0]) + i);
                        if (!ok) damaged[0]++;
                    } catch (RuntimeException e) {
                        damaged[0]++;                                 // a list changing under you can throw, too
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "ledger-writer");
        writer.start();

        List<Integer> shared = new ArrayList<>();
        for (int b = 0; b < batches; b++) {
            List<Integer> batch = reuse ? shared : new ArrayList<>(100);
            batch.clear();                                            // with reuse: clears a list the writer may be reading
            for (int i = 0; i < 100; i++) batch.add(b * 100 + i);
            queue.put(batch);                                         // hand it over, and never touch it again
        }
        writer.join();
        System.out.printf("%s: %,d batches handed over, %,d damaged%n", reuse ? "reused list" : "new list each time", batches, damaged[0]);
    }
}

